import csv
import io
import re


_EXPECTED_WIDTH = 9


def _tolerant_parse(raw_csv):
    rows = []
    row = []
    field = []
    in_quotes = False
    at_field_start = True
    i = 0
    length = len(raw_csv)

    while i < length:
        ch = raw_csv[i]

        if in_quotes:
            if ch == '"':
                if i + 1 < length and raw_csv[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                in_quotes = False
                i += 1
                continue
            field.append(ch)
            i += 1
            continue

        if ch == '"' and at_field_start:
            in_quotes = True
            at_field_start = False
            i += 1
            continue

        if ch == ",":
            row.append("".join(field))
            field = []
            at_field_start = True
            i += 1
            continue

        if ch == "\r" or ch == "\n":
            row.append("".join(field))
            rows.append(row)
            row = []
            field = []
            at_field_start = True
            if ch == "\r" and i + 1 < length and raw_csv[i + 1] == "\n":
                i += 2
            else:
                i += 1
            continue

        field.append(ch)
        at_field_start = False
        i += 1

    if field or row or (length > 0 and raw_csv[-1] == ","):
        row.append("".join(field))
        rows.append(row)

    return rows


def _read_rows(raw_csv):
    try:
        csv.field_size_limit(1000000000)
    except (OverflowError, ValueError):
        pass

    try:
        reader = csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            strict=False,
        )
        return [list(row) for row in reader]
    except (csv.Error, UnicodeError):
        return _tolerant_parse(raw_csv)


def _header_score(row):
    if not row:
        return -1000.0

    score = 0.0
    nonempty = 0
    normalized = []

    for value in row:
        text = value.strip()
        normalized.append(text.casefold())

        if not text:
            score -= 1.0
            continue

        nonempty += 1
        has_alpha = bool(re.search(r"[A-Za-z]", text))
        has_digit = bool(re.search(r"\d", text))

        if "://" in text or re.match(r"^(?:www\.|mailto:)", text, re.I):
            score -= 3.0
        elif not has_alpha:
            score -= 1.5
        else:
            score += 1.0
            if re.match(r"^[A-Za-z_][A-Za-z0-9_ .()/#&'\-]{0,60}$", text):
                score += 1.0

        if len(text) > 100:
            score -= 2.0
        elif len(text) > 60:
            score -= 0.5

        if has_digit and re.match(
            r"^[\s$€£¥+\-]?\d[\d\s,.:/%\-]*$", text
        ):
            score -= 1.5

    if nonempty == 0:
        return -1000.0

    duplicates = len(normalized) - len(set(normalized))
    score -= duplicates * 0.75
    score += nonempty / max(len(row), 1)
    return score


def _find_header_index(rows):
    if not rows:
        return 0

    candidates = [i for i, row in enumerate(rows) if len(row) == _EXPECTED_WIDTH]
    if not candidates:
        candidates = [i for i, row in enumerate(rows) if row]

    if not candidates:
        return 0

    best_index = candidates[0]
    best_score = float("-inf")

    for index in candidates:
        row = rows[index]
        score = _header_score(row)

        if index + 1 < len(rows):
            next_width = len(rows[index + 1])
            if next_width == len(row):
                score += 1.5
            elif next_width == _EXPECTED_WIDTH:
                score += 0.75

        score -= index * 0.0001

        if score > best_score:
            best_score = score
            best_index = index

    return best_index


def _unique_extra_name(existing, number):
    base = "__extra_" + str(number)
    name = base
    suffix = 2
    while name in existing:
        name = base + "_" + str(suffix)
        suffix += 1
    return name


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    rows = _read_rows(raw_csv)
    if not rows:
        return {"columns": [], "rows": []}

    header_index = _find_header_index(rows)
    columns = list(rows[header_index])
    data_rows = [list(row) for row in rows[header_index + 1:]]

    maximum_width = max(
        [_EXPECTED_WIDTH, len(columns)] + [len(row) for row in data_rows]
    )

    existing_names = set(columns)
    extra_number = 1
    while len(columns) < maximum_width:
        name = _unique_extra_name(existing_names, extra_number)
        columns.append(name)
        existing_names.add(name)
        extra_number += 1

    normalized_rows = []
    for row in data_rows:
        if len(row) < maximum_width:
            row = row + [""] * (maximum_width - len(row))
        normalized_rows.append(row)

    return {"columns": columns, "rows": normalized_rows}
